def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 8 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            colored = [(y,x) for y,x in cells if grid[y][x] != 0]
            if not colored:
                continue
            sr0, sr1 = min(y for y,x in colored), max(y for y,x in colored)
            sc0, sc1 = min(x for y,x in colored), max(x for y,x in colored)
            ph, pw = sr1-sr0+1, sc1-sc0+1
            pattern = [[grid[sr0+i][sc0+j] for j in range(pw)] for i in range(ph)]
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    if grid[y][x] != 8:
                        out[y][x] = pattern[(y-sr0)%ph][(x-sc0)%pw]
    return out
